class StatementBacktrack:
  src: str

  def literal(self, k: int, a: str):
    if self.src.startswith(a, k):
      return k + len(a)
    # if self.src.startswith(a, k): print('match', a, 'at', k); return k + len(a)
    # else: print('fail', a, 'at', k); return None

  def ident(self, k: int):
    if k is None or k >= len(self.src):
      return None
    if 'a' <= self.src[k] <= 'z':
      return k + 1
    return None

  def selector(self, k: int):
    # selector ← ('[' ident ']' / '.' ident)*
    r = k
    while k is not None:
      r = k
      s = k
      k = self.literal(s, '[')
      if k is not None:
        k = self.ident(k)
      if k is not None:
        k = self.literal(k, ']')
      if k is None:
        k = self.literal(s, '.')
        if k is not None:
          k = self.ident(k)
    return r

  def statement(self, k: int):
    start = k
    # Alt 1: ident selector ':=' ident
    k = self.ident(start)
    if k is not None:
      k = self.selector(k)
    if k is not None:
      k = self.literal(k, ':=')
    if k is not None:
      k = self.ident(k)
    if k is not None:
      return k

    # Alt 2: ident (',' ident)* ':=' ident (',' ident)*
    k = self.ident(start)
    if k is not None:
      r = k
      while k is not None:
        r = k
        k = self.literal(r, ',')
        if k is not None:
          k = self.ident(k)
      k = r
    if k is not None:
      k = self.literal(k, ':=')
    if k is not None:
      k = self.ident(k)
    if k is not None:
      r = k
      while k is not None:
        r = k
        k = self.literal(r, ',')
        if k is not None:
          k = self.ident(k)
      k = r
    if k is not None:
      return k

    # Alt 3: ident (',' ident)* '←' ident '(' ident ')'
    k = self.ident(start)
    if k is not None:
      r = k
      while k is not None:
        r = k
        k = self.literal(r, ',')
        if k is not None:
          k = self.ident(k)
      k = r
    if k is not None:
      k = self.literal(k, '←')
    if k is not None:
      k = self.ident(k)
    if k is not None:
      k = self.literal(k, '(')
    if k is not None:
      k = self.ident(k)
    if k is not None:
      k = self.literal(k, ')')
    return k

  def parse(self, s: str):
    self.src = s
    return self.statement(0) == len(s)
